const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define location near Beledweyne, Somalia
  const beledweyne = ee.Geometry.Point([45.20, 4.73]);
  const region = beledweyne.buffer(50000); // 50km buffer

  // Define time periods
  const start2017 = '2017-05-01';
  const end2017 = '2017-05-31';
  const start2018 = '2018-05-01';
  const end2018 = '2018-05-31';

  // Get SMAP soil moisture data
  const smap2017 = ee.ImageCollection('NASA/SMAP/SPL4SMGP/007')
    .filterBounds(region)
    .filterDate(start2017, end2017)
    .select('sm_surface');

  const smap2018 = ee.ImageCollection('NASA/SMAP/SPL4SMGP/007')
    .filterBounds(region)
    .filterDate(start2018, end2018)
    .select('sm_surface');

  // Check collection sizes
  const size2017 = await smap2017.size().getInfo();
  const size2018 = await smap2018.size().getInfo();

  console.log(`May 2017 Images: ${size2017}`);
  console.log(`May 2018 Images: ${size2018}`);

  if (size2017 === 0 || size2018 === 0) {
    console.log("One or both periods have no data.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean soil moisture for each period
  const mean2017 = smap2017.mean();
  const mean2018 = smap2018.mean();

  // Get statistics with pixel count
  const stats2017 = await mean2017.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const stats2018 = await mean2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const sm2017 = stats2017.sm_surface_mean;
  const count2017 = stats2017.sm_surface_count;
  const sm2018 = stats2018.sm_surface_mean;
  const count2018 = stats2018.sm_surface_count;

  console.log(`May 2017: Mean=${sm2017}, Pixels=${count2017}`);
  console.log(`May 2018: Mean=${sm2018}, Pixels=${count2018}`);

  // Check for no valid pixels
  if (count2017 === 0 || count2018 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for invalid calculations
  if (sm2017 === null || sm2018 === null || 
      isNaN(sm2017) || isNaN(sm2018) ||
      sm2017 < 0 || sm2018 < 0 || sm2017 > 1 || sm2018 > 1) {
    console.log("Invalid soil moisture values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare soil moisture levels
  console.log(`Difference: ${(sm2018 - sm2017).toFixed(4)} m³/m³`);

  if (sm2018 > sm2017) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
